INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('충북청년희망센터', '상당구 사북로 164 대우타워아파트 5층', NULL, '충북청년희망센터는 충청북도 청년들을 위한 종합 지원 공간으로, 청년 창업·취업·자기계발을 위한 다양한 프로그램과 상담 서비스를 제공합니다. 공간은 개방적이고 자유로운 분위기로 조성되어 있어, 스터디·네트워킹·행사 등을 위한 커뮤니티 활동에 적합합니다. 청년 누구나 편하게 들를 수 있는 접근성 높은 위치에 있으며, 회의실, 공유 오피스, 휴게 공간 등 실용적인 시설이 잘 갖춰져 있습니다.', 36.644547, 127.489097);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('청주시립도서관 동아리교실', '상당구 용암로 55 청주시립도서관 3층 문화교실1', NULL, '청주 시립도서관의 동아리교실은 청년들이 자유롭게 모임을 갖고 활동할 수 있는 공간으로, 다양한 목적의 소모임이나 동아리 활동을 지원하기 위해 마련된 시설입니다.', 36.612333, 127.505739);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('청주오창호수도서관', '청원구 오창읍 오창공원로 102 문화교실4', NULL, '오창호수공원에 위치한 ''문화교실 4''는 청년들이 자유롭게 활용할 수 있는 다목적 커뮤니티 공간입니다. 이 공간은 청년들의 창의적 활동과 교류를 지원하기 위해 마련되었습니다.', 36.712793, 127.423735);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('청주오창도서관', '청원구 오창읍 두릉유리로 1141-10 2층 프로그램실', NULL, '오창도서관의 독서동아리방은 지역 청년들과 시민들이 독서와 토론, 소모임 활동을 자유롭게 진행할 수 있도록 마련된 커뮤니티 공간입니다.', 36.742427, 127.455059);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('금빛도서관', '상당구 호미로 272 3층 문화교실2', NULL, '금빛도서관의 문화교실 2는 청주 시민, 특히 청년들이 다양한 문화 활동과 소모임을 진행할 수 있도록 마련된 다목적 공간입니다. 이 공간은 독서, 학습, 문화예술, 취미 활동 등 다양한 주제로 모임을 구성하여 자유롭게 활동할 수 있도록 지원합니다.', 36.630839, 127.511354);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('오송도서관', '흥덕구 오송읍 오송생명1로 180 오송도서관 3층 동아리실', NULL, '오송도서관의 독서동아리방은 청주 시민과 청년들이 독서와 토론, 소모임 활동을 자유롭게 진행할 수 있도록 마련된 커뮤니티 공간입니다.', 36.634888, 127.323355);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('서원도서관', '서원구 분평로 35 4층 동아리방', NULL, '서원도서관의 독서동아리방은 청주 시민과 청년들이 독서와 토론, 소모임 활동을 자유롭게 진행할 수 있도록 마련된 커뮤니티 공간입니다.', 36.60873, 127.488601);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('가로수도서관', '흥덕구 서현서로 5 동아리실3', NULL, '가로수도서관의 동아리실 3은 청주 시민, 특히 청년들이 다양한 모임과 활동을 자유롭게 진행할 수 있도록 마련된 커뮤니티 공간입니다.', 36.618254, 127.428685);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('충북창조경제혁신센터', '흥덕구 오송생명1로 194-25 SB플라자 2층', NULL, '충북창조경제혁신센터는 충청북도 청주시를 중심으로 지역 창업 생태계 조성과 스타트업 육성을 지원하는 기관입니다. 이 센터는 창업자와 예비 창업자에게 다양한 프로그램과 자원을 제공하여 창의적이고 혁신적인 아이디어가 실제 사업으로 발전할 수 있도록 돕습니다.', 36.637137, 127.32665);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('청년뜨락5959', '상당구 상당로59번길 59 KR', NULL, '청년뜨락5959는 청주시 상당구 상당로 59번길 59에 위치한 청년 전용 복합문화공간으로, 청년들의 다양한 삶을 지원하기 위해 설립된 청주시 청년센터입니다. 청주상공회의소가 위탁 운영하고 있으며, 청년들의 창의적 활동과 커뮤니티 형성을 위한 다양한 프로그램과 공간을 제공합니다.', 36.633536, 127.487306);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('대현지하상가', '상당구 영동 104-13', NULL, '청주시의 대현지하상가는 청년들을 위한 다양한 공간과 프로그램을 제공하는 복합문화공간입니다. 이곳은 청년들의 창업, 문화 활동, 커뮤니티 형성 등을 지원하며, 청주시 중심부에 위치하여 접근성이 뛰어납니다.', 36.636923, 127.4865);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('청년문화창작소 느티', '흥덕구 신율로 138', NULL, '청주시의 청년문화창작소 ''느티''는 청년들이 자유롭게 창작하고 소통할 수 있는 공간으로, 다양한 예술 활동과 문화 프로그램을 통해 청년들의 창의성과 역량을 키우는 데 중점을 두고 있습니다. 이곳은 청년들이 자신의 아이디어를 실현하고, 서로 협업하며 성장할 수 있는 환경을 제공합니다.느티에서는 공연, 전시, 워크숍 등 다양한 문화예술 프로그램이 정기적으로 개최되어, 청년들이 직접 참여하고 경험을 쌓을 수 있는 기회를 제공합니다. 또한, 창작 활동에 필요한 장비와 공간을 지원하여, 청년들이 자신의 프로젝트를 실현하는 데 실질적인 도움을 받을 수 있습니다.', 36.629763, 127.447117);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('청년꿈제작소', '청원구 상당로 314 KR첨단문화산업단지 2층', NULL, '청주시 청년꿈제작소는 청년들의 창의력과 꿈을 실현할 수 있도록 다양한 창작 공간과 프로그램을 제공하는 곳입니다. 대현지하상가 내에 위치해 접근성이 좋고, 청년들이 모여 교류하고 협업할 수 있는 열린 커뮤니티 공간을 갖추고 있습니다. 창업 지원부터 문화예술 활동까지 폭넓게 지원하는 청년 맞춤 공간입니다.', 36.656024, 127.49217);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('청춘잡담', '상당구 북문로3가 44-1 6층', NULL, '청춘잡담은 청주에 위치한 청년 여성들을 위한 소통과 성장의 공간입니다. 편안한 분위기 속에서 취업, 진로, 관계 등 다양한 고민을 나눌 수 있으며, 강연·워크숍·문화 프로그램 등을 통해 자기계발과 네트워킹의 기회를 제공합니다. 여성 청년들이 서로의 이야기에 귀 기울이고 연대할 수 있도록 설계된, 따뜻하고 안전한 커뮤니티 공간입니다.', 36.643938, 127.487419);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('청주테크노s타워', '흥덕구 직지대로 530 청주테크노s타워 동관 212호', NULL, '청주테크노S타워의 공유공간은 청주 지역의 스타트업, 창업자, 청년들을 위한 비즈니스 중심의 개방형 공간입니다. 이 공간은 공유오피스, 회의실, 코워킹 스페이스 등으로 구성되어 있어 창업 초기 기업이나 프리랜서들이 사무공간 없이도 효율적으로 업무를 수행할 수 있도록 지원합니다. 깔끔하고 현대적인 인테리어와 함께, 네트워킹과 협업을 촉진하는 구조로 설계되어 있어 다양한 분야의 사람들이 자유롭게 교류할 수 있는 환경을 제공합니다. 또한, 청주지역 산업단지 및 혁신도시와 인접해 있어 창업 및 비즈니스 활동의 거점 역할을 합니다.', 36.64317, 127.451601);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('더공감 공유오피스', '상당구 산성로98번길 23, 7층 701호', NULL, '더공감공유오피스는 청주시 중심지에 위치한 공유오피스로, 창업자, 프리랜서, 소규모 기업들이 효율적으로 업무를 수행할 수 있는 공간을 제공합니다. 개방형 데스크부터 독립형 사무실까지 다양한 형태의 업무 공간을 갖추고 있으며, 회의실, 휴게 공간 등 부대시설도 마련되어 있어 협업과 네트워킹에 용이합니다.', 36.631136, 127.504954);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('공유오피스 아반', '청원구 오창읍 오창중앙로 123-12 한라트리플타워 4층', NULL, '공유오피스 아반은 청주시 상당구 초정로에 위치한 공유오피스로, 창업자, 프리랜서, 소규모 기업들이 효율적으로 업무를 수행할 수 있는 공간을 제공합니다. 개방형 데스크부터 독립형 사무실까지 다양한 형태의 업무 공간을 갖추고 있으며, 회의실, 휴게 공간 등 부대시설도 마련되어 있어 협업과 네트워킹에 용이합니다.', 36.708997, 127.415991);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('에이플 충북대 중문 스터디 카페', '서원구 1순환로 688', NULL, '에이플(afl) 충북대 중문 스터디 카페는 조용하고 쾌적한 학습 환경을 제공하는 프리미엄 독서실/스터디카페입니다. 좌석은 자유석, 지정석, 그룹 스터디룸 등 다양한 유형으로 구성되어 있으며, 충북대학교 중문 근처에 위치해 학생들이 접근하기 좋습니다. 무인 시스템으로 24시간 운영되어 시간 제약 없이 이용할 수 있고, 전 좌석 콘센트 및 Wi-Fi가 구비되어 있어 학습에 최적화된 공간입니다.', 36.632209, 127.460818);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('위넌스터디카페 충북대점', '흥덕구 사창동 156-10', NULL, '위넌 스터디카페 충북대점은 충북대학교 인근에 위치한 학습 공간으로, 학생들에게 쾌적하고 집중력 있는 환경을 제공합니다. 다양한 좌석 옵션과 24시간 무인 운영 시스템을 갖추고 있어, 시간 제약 없이 자유롭게 이용할 수 있습니다. 또한, 전 좌석에 콘센트와 Wi-Fi가 제공되어 학습에 최적화된 환경을 조성하고 있습니다.', 36.634242, 127.460039);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('에코플러스 스터디카페', '서원구 사창동 번지 5층 156-7', NULL, '에코플러스 스터디카페는 충북대학교 인근에 위치한 학습 공간으로, 학생들에게 쾌적하고 집중력 있는 환경을 제공합니다. 다양한 좌석 옵션과 24시간 무인 운영 시스템을 갖추고 있어, 시간 제약 없이 자유롭게 이용할 수 있습니다. 또한, 전 좌석에 콘센트와 Wi -Fi가 제공되어 학습에 최적화된 환경을 조성하고 있습니다.', 36.634103, 127.46008);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('하우스터디 청주사창센터 스터디카페', '서원구 사창동 번지 5층 231-30', NULL, '하우스터디 청주사창센터 스터디카페는 청주 사창동에 위치한 학습 공간으로, 학생들에게 쾌적하고 집중력 있는 환경을 제공합니다. 다양한 좌석 옵션과 24시간 무인 운영 시스템을 갖추고 있어, 시간 제약 없이 자유롭게 이용할 수 있습니다. 또한, 전 좌석에 콘센트와 Wi-Fi가 제공되어 학습에 최적화된 환경을 조성하고 있습니다.', 36.63535, 127.462856);
INSERT INTO places (name, address, capacity, description, latitude, longitude) VALUES ('별하스터디카페', '흥덕구 봉명동 번지 2층 2748', NULL, '별하스터디카페는 청주 봉명동에 위치한 학습 공간으로, 학생들에게 쾌적하고 집중력 있는 환경을 제공합니다. 다양한 좌석 옵션과 24시간 무인 운영 시스템을 갖추고 있어, 시간 제약 없이 자유롭게 이용할 수 있습니다. 또한, 전 좌석에 콘센트와 Wi-Fi가 제공되어 학습에 최적화된 환경을 조성하고 있습니다.', 36.650294, 127.459244);
